// Kirim LF (0x0A) untuk membangunkan console
// Protocol: kirim LF, tunggu LF+CR response (max 3 attempts)
var attempts = flow.get("davisWakeupAttempts") || 0;

if (attempts >= 3) {
    node.status({fill:"red", shape:"ring", text:"Console not responding (3 attempts)"});
    flow.set("davisWakeupAttempts", 0);
    return null;
}

msg.payload = Buffer.from([0x0A]);
msg.topic = "wakeup";
flow.set("davisWakeupAttempts", attempts + 1);
node.status({fill:"yellow", shape:"dot", text:"Wakeup attempt " + (attempts + 1) + "/3"});
return msg;

// Response parser untuk Davis console
// Deteksi: wakeup response, ACK, LOOP2 packet (99 bytes)

var data = msg.payload;

// 1) Wakeup response: LF+CR (0x0A 0x0D)
if (data.length >= 2 && data[0] === 0x0A && data[1] === 0x0D) {
    flow.set("davisWakeupAttempts", 0);
    flow.set("davisState", "awake");
    var cmd = "LPS 2 1\n";
    msg.payload = cmd;
    node.status({fill:"green", shape:"dot", text:"Console awake - sending LPS 2 1"});
    return [msg, null];
}

// 2) ACK (0x06) - console siap kirim data
if (data.length === 1 && data[0] === 0x06) {
    flow.set("davisState", "receiving");
    node.status({fill:"blue", shape:"dot", text:"ACK received - waiting for LOOP2"});
    return [null, null];
}

// 3) LOOP2 packet - two possible formats from serial timeout:
//    a) 100 bytes: ACK (0x06) + 99-byte LOOP2 delivered together
//    b) 99 bytes: standalone LOOP2 (ACK received in previous message)

function checkLoop2Header(buf, off) {
    return buf[off] === 0x4C && buf[off+1] === 0x4F && buf[off+2] === 0x4F;
}

// Format A: ACK + LOOP2 combined (100 bytes)
if (data.length === 100 && data[0] === 0x06 && checkLoop2Header(data, 1)) {
    if (data[5] === 1) {
        flow.set("davisState", "done");
        node.status({fill:"green", shape:"dot", text:"LOOP2 received (99 bytes)"});
        msg.payload = data.slice(1);
        return [null, msg];
    }
    if (data[5] === 0) {
        node.status({fill:"yellow", shape:"dot", text:"LOOP packet ignored"});
        return [null, null];
    }
}

// Format B: Standalone LOOP2 (99 bytes)
if (data.length === 99 && checkLoop2Header(data, 0)) {
    if (data[4] === 1) {
        flow.set("davisState", "done");
        node.status({fill:"green", shape:"dot", text:"LOOP2 received (99 bytes)"});
        msg.payload = data;
        return [null, msg];
    }
    if (data[4] === 0) {
        node.status({fill:"yellow", shape:"dot", text:"LOOP packet ignored"});
        return [null, null];
    }
}

// 4) Unknown response
node.status({fill:"yellow", shape:"ring", text:"Unknown: " + data.length + " bytes"});

return [null, null];

// Parse Davis LOOP2 Packet (99 bytes)
// Reference: VantageSerialProtocolDocs_v261.md Section X.2
//
// Konversi satuan:
// - Suhu: Â°F â†’ Â°C
// - Angin: mph â†’ m/s
// - Tekanan: inHg â†’ hPa
// - Hujan: clicks â†’ mm (Ã—0.2)
// - ET: inch â†’ mm

var buf = msg.payload;

// ====== STRIP LEADING BYTE ======
// Serial sometimes delivers ACK (0x06) + LOOP2 together as 100 bytes
// Strip the ACK byte so we have a clean 99-byte LOOP2 packet
if (buf.length === 100 && buf[0] === 0x06) {
    buf = buf.slice(1);
}

// ====== VALIDASI ======

// Cek panjang (LOOP2 is exactly 99 bytes)
if (buf.length < 99) {
    node.error("Packet too short: " + buf.length + " bytes");
    return null;
}

// Cek header "LOO" (0x4C 0x4F 0x4F) at offsets 0,1,2
if (buf[0] !== 0x4C || buf[1] !== 0x4F || buf[2] !== 0x4F) {
    node.error("Invalid LOOP2 header");
    return null;
}

// Cek packet type = 1 (LOOP2) at offset 4
if (buf[4] !== 1) {
    node.error("Not a LOOP2 packet, type=" + buf[4]);
    return null;
}

// ====== CRC VALIDATION ======
// CRC-CCITT dari protocol docs halaman 38
var crcTable = [
    0x0000, 0x1021, 0x2042, 0x3063, 0x4084, 0x50A5, 0x60C6, 0x70E7,
    0x8108, 0x9129, 0xA14A, 0xB16B, 0xC18C, 0xD1AD, 0xE1CE, 0xF1EF,
    0x1231, 0x0210, 0x3273, 0x2252, 0x52B5, 0x4294, 0x72F7, 0x62D6,
    0x9339, 0x8318, 0xB37B, 0xA35A, 0xD3BD, 0xC39C, 0xF3FF, 0xE3DE,
    0x2462, 0x3443, 0x0420, 0x1401, 0x64E6, 0x74C7, 0x44A4, 0x5485,
    0xA56A, 0xB54B, 0x8528, 0x9509, 0xE5EE, 0xF5CF, 0xC5AC, 0xD58D,
    0x3653, 0x2672, 0x1611, 0x0630, 0x76D7, 0x66F6, 0x5695, 0x46B4,
    0xB75B, 0xA77A, 0x9719, 0x8738, 0xF7DF, 0xE7FE, 0xD79D, 0xC7BC,
    0x48C4, 0x58E5, 0x6886, 0x78A7, 0x0840, 0x1861, 0x2802, 0x3823,
    0xC9CC, 0xD9ED, 0xE98E, 0xF9AF, 0x8948, 0x9969, 0xA90A, 0xB92B,
    0x5AF5, 0x4AD4, 0x7AB7, 0x6A96, 0x1A71, 0x0A50, 0x3A33, 0x2A12,
    0xDBFD, 0xCBDC, 0xFBBF, 0xEB9E, 0x9B79, 0x8B58, 0xBB3B, 0xAB1A,
    0x6CA6, 0x7C87, 0x4CE4, 0x5CC5, 0x2C22, 0x3C03, 0x0C60, 0x1C41,
    0xEDAE, 0xFD8F, 0xCDEC, 0xDDCD, 0xAD2A, 0xBD0B, 0x8D68, 0x9D49,
    0x7E97, 0x6EB6, 0x5ED5, 0x4EF4, 0x3E13, 0x2E32, 0x1E51, 0x0E70,
    0xFF9F, 0xEFBE, 0xDFDD, 0xCFFC, 0xBF1B, 0xAF3A, 0x9F59, 0x8F78,
    0x9188, 0x81A9, 0xB1CA, 0xA1EB, 0xD10C, 0xC12D, 0xF14E, 0xE16F,
    0x1080, 0x00A1, 0x30C2, 0x20E3, 0x5004, 0x4025, 0x7046, 0x6067,
    0x83B9, 0x9398, 0xA3FB, 0xB3DA, 0xC33D, 0xD31C, 0xE37F, 0xF35E,
    0x02B1, 0x1290, 0x22F3, 0x32D2, 0x4235, 0x5214, 0x6277, 0x7256,
    0xB5EA, 0xA5CB, 0x95A8, 0x8589, 0xF56E, 0xE54F, 0xD52C, 0xC50D,
    0x34E2, 0x24C3, 0x14A0, 0x0481, 0x7466, 0x6447, 0x5424, 0x4405,
    0xA7DB, 0xB7FA, 0x8799, 0x97B8, 0xE75F, 0xF77E, 0xC71D, 0xD73C,
    0x26D3, 0x36F2, 0x0691, 0x16B0, 0x6657, 0x7676, 0x4615, 0x5634,
    0xD94C, 0xC96D, 0xF90E, 0xE92F, 0x99C8, 0x89E9, 0xB98A, 0xA9AB,
    0x5844, 0x4865, 0x7806, 0x6827, 0x18C0, 0x08E1, 0x3882, 0x28A3,
    0xCB7D, 0xDB5C, 0xEB3F, 0xFB1E, 0x8BF9, 0x9BD8, 0xABBB, 0xBB9A,
    0x4A75, 0x5A54, 0x6A37, 0x7A16, 0x0AF1, 0x1AD0, 0x2AB3, 0x3A92,
    0xFD2E, 0xED0F, 0xDD6C, 0xCD4D, 0xBDAA, 0xAD8B, 0x9DE8, 0x8DC9,
    0x7C26, 0x6C07, 0x5C64, 0x4C45, 0x3CA2, 0x2C83, 0x1CE0, 0x0CC1,
    0xEF1F, 0xFF3E, 0xCF5D, 0xDF7C, 0xAF9B, 0xBFBA, 0x8FD9, 0x9FF8,
    0x6E17, 0x7E36, 0x4E55, 0x5E74, 0x2E93, 0x3EB2, 0x0ED1, 0x1EF0
];

var crc = 0;
for (var i = 0; i < 99; i++) {
    crc = crcTable[((crc >> 8) ^ buf[i]) & 0xFF] ^ ((crc << 8) & 0xFFFF);
}
var crcValid = (crc === 0);

if (!crcValid) {
    node.warn("CRC invalid: 0x" + crc.toString(16) + " - data mungkin corrupt");
}

// ====== HELPER FUNCTIONS ======

function readUInt16LE(buffer, offset) {
    return buffer[offset] | (buffer[offset + 1] << 8);
}

function readInt16LE(buffer, offset) {
    var val = readUInt16LE(buffer, offset);
    if (val > 32767) val -= 65536;
    return val;
}

function fToC(f) {
    if (f === 255 || f === 32767 || f === -32768) return null;
    return Math.round(((f - 32) * 5 / 9) * 100) / 100;
}

function fOffset90ToC(val) {
    if (val === 255) return null;
    return fToC(val - 90);
}

function mphToMs(mph) {
    if (mph === 255 || mph === 32767 || mph === 65535) return null;
    return Math.round(mph * 0.44704 * 100) / 100;
}

function tenthsMphToMs(val) {
    if (val === 32767 || val === 65535) return null;
    return Math.round(val * 0.1 * 0.44704 * 100) / 100;
}

function inHgToHpa(inHg) {
    if (inHg === 0 || inHg === 32767) return null;
    return Math.round(inHg * 0.0338639 * 100) / 100;
}

function clicksToMm(clicks) {
    if (clicks === 32767 || clicks === 65535) return null;
    return Math.round(clicks * 0.2 * 100) / 100;
}

function milsToMm(mils) {
    if (mils === 32767 || mils === 65535) return null;
    return Math.round(mils * 0.0254 * 100) / 100;
}

function barTrendText(val) {
    if (val === 196 || val === -60) return "Falling Rapidly";
    if (val === 236 || val === -20) return "Falling Slowly";
    if (val === 0) return "Steady";
    if (val === 20) return "Rising Slowly";
    if (val === 60) return "Rising Rapidly";
    return "Unknown (" + val + ")";
}

function parseStormDate(val) {
    if (val === 0 || val === 32767 || val === 65535) return null;
    var year = (val & 0x7F) + 2000;
    var day = (val >> 7) & 0x1F;
    var month = (val >> 12) & 0x0F;
    return year + "-" + ("0" + month).slice(-2) + "-" + ("0" + day).slice(-2);
}

function parseTime(val) {
    if (val === 0 || val === 32767 || val === 65535) return null;
    var hour = Math.floor(val / 100);
    var min = val % 100;
    return ("0" + hour).slice(-2) + ":" + ("0" + min).slice(-2);
}

// ====== PARSE ALL FIELDS ======

// Offset 3: Bar Trend
var barTrend = buf[3];

// Offset 7-8: Barometer (inHg / 1000)
var barometerRaw = readUInt16LE(buf, 7);
var barometerInHg = barometerRaw / 1000.0;
var barometerHpa = inHgToHpa(barometerRaw);

// Offset 9-10: Inside Temperature (Â°F / 10)
// Check raw int before division to avoid floating point comparison issues
var insideTempRaw = readInt16LE(buf, 9);
var insideTempC = (insideTempRaw === 32767 || insideTempRaw === -32768) ? null : fToC(insideTempRaw / 10.0);

// Offset 11: Inside Humidity
var insideHumidity = buf[11];

// Offset 12-13: Outside Temperature (Â°F / 10)
// Check raw int before division to avoid floating point comparison issues
var outsideTempRaw = readInt16LE(buf, 12);
var outsideTempC = (outsideTempRaw === 32767 || outsideTempRaw === -32768) ? null : fToC(outsideTempRaw / 10.0);

// Offset 14: Wind Speed (mph)
var windSpeedRaw = buf[14];
var windSpeedMs = mphToMs(windSpeedRaw);

// Offset 16-17: Wind Direction (degrees)
var windDirection = readUInt16LE(buf, 16);
if (windDirection === 0) windDirection = null;

// Offset 18-19: 10-Min Avg Wind Speed (0.1 mph)
var windAvg10Raw = readUInt16LE(buf, 18);
var windAvg10Ms = tenthsMphToMs(windAvg10Raw);

// Offset 20-21: 2-Min Avg Wind Speed (0.1 mph)
var windAvg2Raw = readUInt16LE(buf, 20);
var windAvg2Ms = tenthsMphToMs(windAvg2Raw);

// Offset 22-23: 10-Min Wind Gust (0.1 mph)
var windGustRaw = readUInt16LE(buf, 22);
var windGustMs = tenthsMphToMs(windGustRaw);

// Offset 24-25: Wind Direction for 10-Min Gust
var gustDirection = readUInt16LE(buf, 24);
if (gustDirection === 0) gustDirection = null;

// Offset 30-31: Dew Point (Â°F, 255=dashed)
var dewPointRaw = readInt16LE(buf, 30);
var dewPointC = fToC(dewPointRaw);

// Offset 33: Outside Humidity
var outsideHumidity = buf[33];

// Offset 35-36: Heat Index (Â°F, 255=dashed)
var heatIndexRaw = readInt16LE(buf, 35);
var heatIndexC = fToC(heatIndexRaw);

// Offset 37-38: Wind Chill (Â°F, 255=dashed)
var windChillRaw = readInt16LE(buf, 37);
var windChillC = fToC(windChillRaw);

// Offset 39-40: THSW Index (Â°F, 255=dashed)
var thswRaw = readInt16LE(buf, 39);
var thswC = fToC(thswRaw);

// Offset 41-42: Rain Rate (clicks/hr)
var rainRateRaw = readUInt16LE(buf, 41);
var rainRateMmhr = clicksToMm(rainRateRaw);

// Offset 43: UV Index
var uvIndex = buf[43];
if (uvIndex === 255) uvIndex = null;

// Offset 44-45: Solar Radiation (W/mÂ²)
var solarRadiation = readUInt16LE(buf, 44);
if (solarRadiation === 32767 || solarRadiation === 65535) solarRadiation = null;

// Offset 46-47: Storm Rain (clicks)
var stormRainRaw = readUInt16LE(buf, 46);
var stormRainMm = clicksToMm(stormRainRaw);

// Offset 48-49: Storm Start Date
var stormStartDate = parseStormDate(readUInt16LE(buf, 48));

// Offset 50-51: Daily Rain (clicks)
var dayRainRaw = readUInt16LE(buf, 50);
var dayRainMm = clicksToMm(dayRainRaw);

// Offset 52-53: Last 15-min Rain (clicks)
var last15RainRaw = readUInt16LE(buf, 52);
var last15RainMm = clicksToMm(last15RainRaw);

// Offset 54-55: Last Hour Rain (clicks)
var lastHourRainRaw = readUInt16LE(buf, 54);
var lastHourRainMm = clicksToMm(lastHourRainRaw);

// Offset 56-57: Daily ET (0.001 inch)
var dayEtRaw = readUInt16LE(buf, 56);
var dayEtMm = milsToMm(dayEtRaw);

// Offset 58-59: Last 24-Hour Rain (clicks)
var last24hrRainRaw = readUInt16LE(buf, 58);
var last24hrRainMm = clicksToMm(last24hrRainRaw);

// Offset 60: Bar Reduction Method
var barReductionMethod = buf[60];
var barReductionText = "Unknown";
if (barReductionMethod === 0) barReductionText = "User Offset";
else if (barReductionMethod === 1) barReductionText = "Altimeter Setting";
else if (barReductionMethod === 2) barReductionText = "NOAA Bar Reduction";

// Offset 61-62: User Barometric Offset (0.001 inHg)
var userBarOffsetRaw = readInt16LE(buf, 61);
var userBarOffsetHpa = Math.round(userBarOffsetRaw * 0.0338639 * 100) / 100;

// Offset 63-64: Barometric Calibration (0.001 inHg)
var barCalRaw = readInt16LE(buf, 63);
var barCalHpa = Math.round(barCalRaw * 0.0338639 * 100) / 100;

// Offset 65-66: Barometric Sensor Raw Reading (0.001 inHg)
var barSensorRaw = readUInt16LE(buf, 65);
var barSensorHpa = Math.round(barSensorRaw * 0.0338639 * 100) / 100;

// Offset 67-68: Absolute Barometric Pressure (0.001 inHg)
var barAbsoluteRaw = readUInt16LE(buf, 67);
var barAbsoluteHpa = Math.round(barAbsoluteRaw * 0.0338639 * 100) / 100;

// Offset 69-70: Altimeter Setting (0.001 inHg)
var altimeterRaw = readUInt16LE(buf, 69);
var altimeterHpa = Math.round(altimeterRaw * 0.0338639 * 100) / 100;

// ====== BUILD OUTPUT JSON ======

var output = {
    timestamp: new Date().toISOString(),
    crcValid: crcValid,
    packetType: "LOOP2",
    inside: {
        temperature_celsius: insideTempC,
        humidity_percent: insideHumidity
    },
    outside: {
        temperature_celsius: outsideTempC,
        humidity_percent: outsideHumidity,
        dewpoint_celsius: dewPointC,
        heatindex_celsius: heatIndexC,
        windchill_celsius: windChillC,
        thsw_index_celsius: thswC
    },
    barometer: {
        pressure_hpa: barometerHpa,
        trend: barTrendText(barTrend),
        reduction_method: barReductionText,
        absolute_hpa: barAbsoluteHpa,
        altimeter_hpa: altimeterHpa,
        raw_sensor_hpa: barSensorHpa,
        user_offset_hpa: userBarOffsetHpa,
        calibration_hpa: barCalHpa
    },
    wind: {
        speed_ms: windSpeedMs,
        direction_degrees: windDirection,
        avg_10min_ms: windAvg10Ms,
        avg_2min_ms: windAvg2Ms,
        gust_ms: windGustMs,
        gust_direction_degrees: gustDirection
    },
    rain: {
        rate_mmhr: rainRateMmhr,
        daily_mm: dayRainMm,
        last_15min_mm: last15RainMm,
        last_hour_mm: lastHourRainMm,
        last_24hr_mm: last24hrRainMm,
        storm_mm: stormRainMm,
        storm_start: stormStartDate
    },
    solar: {
        uv_index: uvIndex,
        radiation_wm2: solarRadiation
    },
    et: {
        daily_mm: dayEtMm
    }
};

// Simpan ke flow context
flow.set("davisWeatherData", output);
flow.set("davisLastUpdate", output.timestamp);

msg.payload = output;
return msg;

// Simpan data LOOP2 ke flow context
var data = msg.payload;

flow.set("davisLastData", data);
flow.set("davisLastUpdate", new Date().toISOString());

node.status({fill:"green", shape:"dot", text:"Updated: " + new Date().toLocaleTimeString()});

msg.payload = data;
return msg;
